tool_and_message_events.command:
/bin/bash -lc 'set -euo pipefail
checkout=$(mktemp -d -p "$PWD" .contract-check.XXXXXXXX)
trap '"'find \""'$checkout" -depth -delete'"' EXIT
cp -R release/. \""'$checkout/"
tarball="$PWD/vendor/hono-4.13.19.tgz"
cd "$checkout"
node --version
npm_config_cache="$checkout/.npm-cache" npm install --offline --ignore-scripts --no-audit --no-fund "$tarball"
npm ls hono
npm test
node --input-type=module <<'"'JS'
import assert from 'node:assert/strict';
import app from './app.mjs';

const cases = [
  {name: 'valid', id: 'k8', shift: 'day', status: 200, body: {id: 'k8', title: 'River'}, steps: 'dispatch,session,read'},
  {name: 'no session', id: 'k8', status: 401, body: {error: 'sign_in'}, steps: 'dispatch,session'},
  {name: 'missing record', id: 'missing', shift: 'day', status: 404, body: {error: 'not_found'}, steps: 'dispatch,session,read'},
  {name: 'invalid supplied record', id: 'm3', shift: 'day', status: 502, body: {error: 'invalid_record'}, steps: 'dispatch,session,read,error'},
];
let failures = 0;
for (const {name, id, shift, status, body, steps} of cases) {
  const response = await app.request(new Request(new URL('/desk/' + id, 'http://localhost'), {
    headers: shift ? {'x-shift': shift} : {},
  }));
  assert.ok(response instanceof Response);
  const actual = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  const contentType = response.headers.get('content-type');
  try {
    assert.deepEqual(actual, {status, body, steps});
    assert.match(contentType, /"'^application'"\\/json(?:;|"'$)/);
    console.log('"'PASS', name, JSON.stringify({...actual, contentType}));
  } catch {
    failures++;
    console.log('FAIL', name, JSON.stringify({expected: {status, body, steps}, actual: {...actual, contentType}}));
  }
}
if (failures) process.exitCode = 1;
JS"

